<?php $edit = $sectionData['edit'] ?? null; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Marketplace partners</span><h2><?= $edit ? 'Edit vendor' : 'Add a vendor' ?></h2><p>Keep public vendor links and marketplace references organized. Credentials do not belong here.</p></div></div>
  <form class="admin-form-card admin-compact-form" method="post" action="<?= $this->escape(appUrl('/admin/vendors/save')) ?>">
    <input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>">
    <div class="form-grid"><div class="field"><label for="vendor-name">Vendor name *</label><input id="vendor-name" name="name" maxlength="150" value="<?= $this->escape($edit['name'] ?? '') ?>" required></div><div class="field"><label for="vendor-platform">Platform *</label><input id="vendor-platform" name="platform_type" maxlength="50" value="<?= $this->escape($edit['platform_type'] ?? '') ?>" placeholder="Marketplace, payment provider, etc." required></div></div>
    <div class="form-grid"><div class="field"><label for="vendor-url">Website URL</label><input id="vendor-url" name="website_url" type="url" value="<?= $this->escape($edit['website_url'] ?? '') ?>" placeholder="https://"></div><div class="field"><label for="vendor-account">Account identifier</label><input id="vendor-account" name="account_identifier" maxlength="190" value="<?= $this->escape($edit['account_identifier'] ?? '') ?>"></div></div>
    <div class="field"><label for="vendor-status">Status</label><select id="vendor-status" name="status"><option value="active" <?= ($edit['status'] ?? 'active') === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= ($edit['status'] ?? '') === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></div>
    <div class="admin-form-footer"><button class="button" type="submit"><?= $edit ? 'Save vendor' : 'Add vendor' ?></button><?php if ($edit): ?><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/vendors')) ?>">Cancel</a><?php endif ?></div>
  </form>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Operations</span><h2>Vendors <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No vendors have been added.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Vendor</th><th>Platform</th><th>Website</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['name']) ?></strong><small class="table-subtext"><?= $this->escape($record['account_identifier'] ?: 'No account identifier') ?></small></td><td><?= $this->escape($record['platform_type']) ?></td><td><?php if ($record['website_url']): ?><a class="text-link" href="<?= $this->escape($record['website_url']) ?>" target="_blank" rel="noopener noreferrer">Visit <i data-lucide="external-link"></i></a><?php else: ?>—<?php endif ?></td><td><span class="status-badge status-<?= $this->escape($record['status']) ?>"><?= $this->escape(ucfirst($record['status'])) ?></span></td><td><a class="admin-icon-link" aria-label="Edit <?= $this->escape($record['name']) ?>" href="<?= $this->escape(appUrl('/admin/vendors?id=' . (int) $record['id'])) ?>"><i data-lucide="pencil"></i></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
